	/**
	 * آیا نماد فعال است؟
	 *
	 * @return bool
	 */
	public static function use_symbol() {
		return '1' === Ardal_Palette::get( 'toman_symbol' );
	}

	/**
	 * اتصال به نمایش قیمت خود ووکامرس.
	 *
	 * عمداً فیلتر `woocommerce_currency_symbol` استفاده نشده: آن رشته علاوه بر
	 * نمایش سمت کاربر، در ایمیل‌ها (از جمله نسخهٔ متنی)، ستون‌های پیشخوان، REST،
	 * خروجی‌های CSV و متغیرهای جاوااسکریپتِ فرمت عدد هم به کار می‌رود و تزریق SVG
	 * به آن، همهٔ این‌ها را خراب می‌کند. به‌جایش فقط HTML نمایشِ سمت کاربر فیلتر
	 * می‌شود و محتوای همان span نماد واحد پول جایگزین می‌گردد.
	 */
	public static function init() {
		add_action( 'init', array( __CLASS__, 'register_woo_filters' ) );
	}

	public static function register_woo_filters() {
		if ( ! self::use_symbol() || '1' !== Ardal_Palette::get( 'toman_woo' ) ) {
			return;
		}

		if ( ! class_exists( 'WooCommerce' ) ) {
			return;
		}

		$filters = array(
			'woocommerce_get_price_html',              // قیمت محصول در فروشگاه، آرشیو و صفحه محصول
			'woocommerce_cart_item_price',             // قیمت واحد در سبد خرید
			'woocommerce_cart_item_subtotal',          // جمع هر ردیف سبد
			'woocommerce_cart_subtotal',               // جمع کل سبد
			'woocommerce_cart_totals_fee_html',        // هزینه‌های اضافه
			'woocommerce_cart_totals_order_total_html', // مبلغ نهایی سبد و تسویه
		);

		foreach ( $filters as $filter ) {
			add_filter( $filter, array( __CLASS__, 'swap_in_price_html' ), 99 );
		}
	}

	/**
	 * آیا در بستری هستیم که جایگزینی امن است؟
	 *
	 * @return bool
	 */
	private static function frontend_context() {
		if ( defined( 'REST_REQUEST' ) && REST_REQUEST ) {
			return false;
		}

		if ( function_exists( 'wp_doing_cron' ) && wp_doing_cron() ) {
			return false;
		}

		// admin-ajax برای فرگمنت‌های سبد خرید هم is_admin() را true می‌کند.
		if ( is_admin() && ! wp_doing_ajax() ) {
			return false;
		}

		return true;
	}

	/**
	 * آیا این متن واحد پول، تومان است؟
	 *
	 * اگر فروشگاه واحد دیگری داشته باشد (ریال، دلار و …) دست نمی‌خورد.
	 *
	 * @param string $text
	 * @return bool
	 */
	private static function is_toman( $text ) {
		// ووکامرس نماد بعضی واحدها (از جمله IRT) را به‌صورت entity نگه می‌دارد،
		// مثل &#x062A;&#x0648;&#x0645;&#x0627;&#x0646; برای «تومان».
		$text = trim( html_entity_decode( (string) $text, ENT_QUOTES, 'UTF-8' ) );

		if ( '' === $text ) {
			return false;
		}

		foreach ( array( 'تومان', 'تومن', 'toman', 'irt' ) as $needle ) {
			if ( false !== mb_stripos( $text, $needle ) ) {
				return true;
			}
		}

		// اگر واحد فروشگاه IRT است، هر نمادی که ووکامرس چاپ کند تومان محسوب می‌شود.
		return function_exists( 'get_woocommerce_currency' ) && 'IRT' === get_woocommerce_currency();
	}

	/**
	 * جایگزینی متن واحد پول با نماد، داخل HTML قیمت ووکامرس.
	 *
	 * @param mixed $html
	 * @return mixed
	 */
	public static function swap_in_price_html( $html ) {
		if ( ! is_string( $html ) || '' === $html || ! self::frontend_context() ) {
			return $html;
		}

		if ( false === strpos( $html, 'woocommerce-Price-currencySymbol' ) ) {
			return $html;
		}

		$out = preg_replace_callback(
			'#(<span[^>]*class="[^"]*woocommerce-Price-currencySymbol[^"]*"[^>]*>)(.*?)(</span>)#isu',
			static function ( $m ) {
				if ( ! self::is_toman( wp_strip_all_tags( $m[2] ) ) ) {
					return $m[0];
				}

				return $m[1] . self::symbol() . $m[3];
			},
			$html
		);

		// اگر رشته UTF-8 معتبر نبود preg مقدار null می‌دهد؛ آن وقت دست‌نخورده برگردد.
		return null === $out ? $html : $out;
	}

	/**
	 * واحد پول کنار قیمت.
	 *
	 * خروجی همیشه یک span با کلاس ard-currency است تا اندازه و رنگش از CSS بیاید
	 * و جای متن و نماد در همهٔ ویجت‌ها یکسان بماند.
	 *
	 * @return string
	 */
	public static function unit() {
		if ( self::use_symbol() ) {
			return '<span class="ard-currency ard-currency--icon">' . self::symbol() . '</span>';
		}

		return '<span class="ard-currency ard-currency--text">تومان</span>';
	}
}
